#define MAXN 200005

char s[MAXN];
int pi[MAXN];
long long cnt[26];

int main() {
    // Read input: string s, l, r
    long long l, r;
    scanf("%s %lld %lld", s, &l, &r);
    int n = strlen(s);

    // Compute prefix function (KMP) to find shortest even string from s
    pi[0] = 0;
    for (int i = 1; i < n; i++) {
        int j = pi[i-1];
        while (j > 0 && s[i] != s[j])
            j = pi[j-1];
        if (s[i] == s[j])
            j++;
        pi[i] = j;
    }

    // Length of shortest even string after first f(S)
    int border = pi[n-1];
    int add = n - border;
    // The even string T is s[0..n-1] + s[border..n-1] if border exists, else double the whole
    // Actually: shortest even string = s + s[border..n-1]
    // Let's build T in a temporary way:
    char T[MAXN*2];
    int tlen = 0;
    for (int i = 0; i < n; i++) T[tlen++] = s[i];
    for (int i = border; i < n; i++) T[tlen++] = s[i];

    // Count letters in one T
    long long cntT[26] = {0};
    for (int i = 0; i < tlen; i++) {
        cntT[T[i]-'a']++;
    }

    // Now final string = T repeated K times, where K = 2^(10^100 - 1) but we treat as huge
    // Actually after first f we have T, then each next f doubles: T -> TT -> TTTT ...
    // So after 10^100 applications total, we have T repeated 2^(10^100 - 1) times.
    // We don't need exact K, we just need counts in [l, r].
    // We can compute directly with modulo arithmetic on positions.

    l--; r--; // convert to 0-based

    // Compute number of full T blocks before l and before r+1
    long long block_start_l = l / tlen;
    long long block_start_r = r / tlen;

    long long offset_l = l % tlen;
    long long offset_r = r % tlen;

    long long total_blocks = block_start_r - block_start_l - 1;
    if (total_blocks > 0) {
        for (int i = 0; i < 26; i++) {
            cnt[i] += total_blocks * cntT[i];
        }
    }

    // Partial first block
    if (block_start_l == block_start_r) {
        // Same block
        for (long long i = offset_l; i <= offset_r; i++) {
            cnt[T[i]-'a']++;
        }
    } else {
        // First block part
        for (long long i = offset_l; i < tlen; i++) {
            cnt[T[i]-'a']++;
        }
        // Last block part
        for (long long i = 0; i <= offset_r; i++) {
            cnt[T[i]-'a']++;
        }
    }

    // Output
    for (int i = 0; i < 26; i++) {
        printf("%lld ", cnt[i]);
    }
    printf("\n");

    return 0;
}

