typedef long long ll;

static void add_counts_prefix(const char *s, int n, ll x, ll out[26]) {
    for (int i = 0; i < 26; ++i) out[i] = 0;
    for (ll i = 0; i < x; ++i) out[s[i % n] - 'a']++;
}

int main(void) {
    char s[200005];
    ll l, r;

    if (scanf("%s %lld %lld", s, &l, &r) != 3) return 0;

    int n = (int)strlen(s);

    /*
      After applying f infinitely many times, the resulting infinite string
      is periodic with period equal to the primitive root of S.
      Since S is even, repeated shortest-even completion converges to
      infinite repetition of the smallest period of S.

      So we:
      1) Find the smallest period p of S.
      2) Count letters in substring [l, r] (1-indexed) of the infinite
         periodic string built from S[0..p-1].
    */

    int *pi = (int *)malloc(n * sizeof(int));
    pi[0] = 0;
    for (int i = 1; i < n; ++i) {
        int j = pi[i - 1];
        while (j > 0 && s[i] != s[j]) j = pi[j - 1];
        if (s[i] == s[j]) j++;
        pi[i] = j;
    }

    int p = n - pi[n - 1];
    if (n % p != 0) p = n;

    ll per[26] = {0};
    for (int i = 0; i < p; ++i) per[s[i] - 'a']++;

    ll prefR[26], prefL[26];
    ll R = r;
    ll L = l - 1;

    ll fullR = R / p, remR = R % p;
    ll fullL = L / p, remL = L % p;

    for (int i = 0; i < 26; ++i) {
        prefR[i] = fullR * per[i];
        prefL[i] = fullL * per[i];
    }

    ll tmp[26];
    add_counts_prefix(s, p, remR, tmp);
    for (int i = 0; i < 26; ++i) prefR[i] += tmp[i];

    add_counts_prefix(s, p, remL, tmp);
    for (int i = 0; i < 26; ++i) prefL[i] += tmp[i];

    for (int i = 0; i < 26; ++i) {
        if (i) printf(" ");
        printf("%lld", prefR[i] - prefL[i]);
    }
    printf("\n");

    free(pi);
    return 0;
}

