string f(const string &s) {
    int n = s.size();
    // find the smallest period
    for (int p = 1; p <= n; ++p) {
        if (n % p == 0) {
            bool ok = true;
            for (int i = 0; i < n; ++i) {
                if (s[i] != s[i % p]) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                string t = s.substr(0, p);
                string res = s;
                // extend to shortest even string
                while (res.size() % 2 != 0 || res.substr(0, res.size()/2) != res.substr(res.size()/2)) {
                    res += t;
                }
                return res;
            }
        }
    }
    return s;
}

