int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S;
    long long l, r;
    cin >> S >> l >> r;

    int n = (int)S.size();

    // Build KMP prefix-function to find the shortest even string f(S).
    // We need the smallest t such that S + suffix = XX.
    // Equivalent: find the longest border that lets total length become even.
    vector<int> pi(n, 0);
    for (int i = 1; i < n; ++i) {
        int j = pi[i - 1];
        while (j > 0 && S[i] != S[j]) j = pi[j - 1];
        if (S[i] == S[j]) ++j;
        pi[i] = j;
    }

    // Let final even string length be 2*m, first half H.
    // Since result starts with S, H must be a prefix of S if |H| >= |S|/2.
    // Minimal extension is obtained by taking the smallest m >= ceil(n/2)
    // such that prefix of length n-m equals suffix of S of same length.
    int bestM = -1;
    for (int m = (n + 1) / 2; m <= n; ++m) {
        int k = n - m; // overlap length between second half prefix and suffix of S
        bool ok = false;
        if (k == 0) ok = true;
        else {
            int x = pi[n - 1];
            while (true) {
                if (x == k) { ok = true; break; }
                if (x < k) break;
                x = pi[x - 1];
            }
        }
        if (ok) {
            bestM = m;
            break;
        }
    }

    string H = S.substr(0, bestM);
    string T = H + H; // f(S)

    // After one application to an even string XX:
    // f(XX) = X next(X), where next(X) is lexicographic increment in base-26.
    // Repeating on even strings evolves only the right half by +1 each time.
    //
    // After enormously many times (10^100), this is effectively the bi-infinite
    // sequence formed by concatenating consecutive strings of fixed length |H|
    // in base-26, starting far enough that only stationarity matters locally.
    //
    // For any queried finite interval, counts equal those in the infinite periodic
    // distribution over all strings of length m:
    // each position independently cycles uniformly through 'a'..'z'.
    //
    // Thus over blocks of length m*26, each letter appears exactly m times per
    // block-position aggregation => total block count for each letter is blockLen/26.
    //
    // More concretely, define the infinite word W as concatenation of all length-m
    // base-26 strings in order. Since 10^100 is astronomically large, any fixed
    // [l,r] lies inside this stabilized regime. We compute exact counts in W.

    int m = bestM;

    auto charAt = [&](long long pos) -> int {
        // 1-indexed position in W
        long long block = (pos - 1) / m;      // which length-m string
        int idx = (int)((pos - 1) % m);       // position inside string, 0-based
        // digit at idx in base-26 representation of block with exactly m digits
        // most significant digit first
        int shift = m - 1 - idx;
        while (shift--) block /= 26;
        return (int)(block % 26);
    };

    auto prefixCounts = [&](long long x) {
        array<long long, 26> res{};
        if (x <= 0) return res;

        // Count over first x positions of W.
        // For each position within a length-m string, digits cycle with period 26^(m-pos).
        // But m can be moderate; x is only up to 1e18 typically. Simpler digit-DP style formula.

        long long fullStrings = x / m;
        int rem = (int)(x % m);

        // Count contributions from complete strings 0 .. fullStrings-1
        // For each digit position p (0-based from left), digit cycles every 26^(m-1-p).
        vector<unsigned long long> pw(m + 1, 1);
        for (int i = 1; i <= m; ++i) {
            if (pw[i - 1] > ULLONG_MAX / 26ULL) pw[i] = ULLONG_MAX;
            else pw[i] = pw[i - 1] * 26ULL;
        }

        for (int p = 0; p < m; ++p) {
            unsigned long long base = pw[m - 1 - p];
            unsigned long long period = (base >= ULLONG_MAX / 26ULL ? ULLONG_MAX : base * 26ULL);

            unsigned long long N = (unsigned long long)fullStrings;
            if (base == ULLONG_MAX || period == ULLONG_MAX) {
                // base too large => fullStrings is certainly smaller, so all leading digits are zero
                res[0] += (long long)N;
            } else {
                unsigned long long full = N / period;
                unsigned long long remN = N % period;
                for (int d = 0; d < 26; ++d) {
                    unsigned long long add = full * base;
                    unsigned long long L = (unsigned long long)d * base;
                    unsigned long long R = L + base;
                    if (remN > L) add += min(remN, R) - L;
                    res[d] += (long long)add;
                }
            }
        }

        // Remaining prefix of next string
        unsigned long long b = (unsigned long long)fullStrings;
        for (int p = 0; p < rem; ++p) {
            int shift = m - 1 - p;
            unsigned long long t = b;
            while (shift--) t /= 26ULL;
            int d = (int)(t % 26ULL);
            res[d]++;
        }

        return res;
    };

    auto A = prefixCounts(r);
    auto B = prefixCounts(l - 1);

    for (int i = 0; i < 26; ++i) {
        if (i) cout << ' ';
        cout << (A[i] - B[i]);
    }
    cout << '\n';

    return 0;
}

