import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int[] zFunction(String s) {
        int n = s.length();
        int[] z = new int[n];
        int l = 0, r = 0;
        for (int i = 1; i < n; i++) {
            if (i <= r) z[i] = Math.min(r - i + 1, z[i - l]);
            while (i + z[i] < n && s.charAt(z[i]) == s.charAt(i + z[i])) z[i]++;
            if (i + z[i] - 1 > r) {
                l = i;
                r = i + z[i] - 1;
            }
        }
        z[0] = n;
        return z;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        String s = fs.next();
        long l = fs.nextLong();
        long r = fs.nextLong();

        int n = s.length();

        // Let T be the infinite periodic string with minimal period p,
        // where p is the minimal period of S.
        // Repeatedly applying f eventually converges to prefixes of T,
        // and after 10^100 times it is effectively T.
        //
        // So we need counts on T[l..r] (1-indexed).

        int[] z = zFunction(s);
        int p = n;
        for (int i = 1; i < n; i++) {
            if (n % i == 0 && z[i] >= n - i) {
                p = i;
                break;
            }
        }

        String base = s.substring(0, p);

        long[][] pref = new long[p + 1][26];
        for (int i = 0; i < p; i++) {
            System.arraycopy(pref[i], 0, pref[i + 1], 0, 26);
            pref[i + 1][base.charAt(i) - 'a']++;
        }

        long[] perCnt = pref[p];

        long[] ans = countUpTo(r, p, pref, perCnt);
        long[] left = countUpTo(l - 1, p, pref, perCnt);

        StringBuilder out = new StringBuilder();
        for (int i = 0; i < 26; i++) {
            if (i > 0) out.append(' ');
            out.append(ans[i] - left[i]);
        }
        System.out.println(out);
    }

    static long[] countUpTo(long x, int p, long[][] pref, long[] perCnt) {
        long[] res = new long[26];
        if (x <= 0) return res;

        long full = x / p;
        int rem = (int) (x % p);

        for (int i = 0; i < 26; i++) {
            res[i] = full * perCnt[i] + pref[rem][i];
        }
        return res;
    }
}

import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    S = data[0]
    l = int(data[1])
    r = int(data[2])

    n = len(S)

    # Find minimal period p
    p = n
    for period in range(1, n + 1):
        ok = True
        for i in range(n):
            if S[i] != S[i % period]:
                ok = False
                break
        if ok:
            p = period
            break

    # Count letters in one period
    period_counts = [0] * 26
    for ch in S[:p]:
        period_counts[ord(ch) - 97] += 1

    result = [0] * 26
    # Count for range [l, r] (1-indexed)
    for i in range(26):
        total = 0
        # Full periods
        full_periods = (r - l + 1) // p
        total += full_periods * period_counts[i]

        # Remaining part
        start_rem = (l - 1) % p
        end_rem = (r - 1) % p
        if (r - l + 1) % p != 0:
            if start_rem <= end_rem:
                for idx in range(start_rem, end_rem + 1):
                    if ord(S[idx]) - 97 == i:
                        total += 1
            else:
                for idx in range(start_rem, p):
                    if ord(S[idx]) - 97 == i:
                        total += 1
                for idx in range(0, end_rem + 1):
                    if ord(S[idx]) - 97 == i:
                        total += 1
        result[i] = total

    sys.stdout.write(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
